import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Material Design","description":"Material Design 1.1.0 für Studio 0.1.292 mit DE/EN/FR und kompatiblen Updates.","frontmatter":{"title":"Material Design","description":"Material Design 1.1.0 für Studio 0.1.292 mit DE/EN/FR und kompatiblen Updates."},"headers":[],"relativePath":"projects/grafik-visual-studio/materialdesign.md","filePath":"projects/grafik-visual-studio/materialdesign.md","lastUpdated":1792778683000}'),a={name:"projects/grafik-visual-studio/materialdesign.md"};function s(d,e,l,o,u,g){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="material-design" tabindex="-1">Material Design <a class="header-anchor" href="#material-design" aria-label="Permalink to &quot;Material Design&quot;">​</a></h1><p>Ab <strong>Studio 0.1.295</strong> füllen die Paket-Icons samt Symbolbereich ihren Rahmen in Seitenleiste und Widget-Auswahl. Die Paketgrafiken und Einstellungen bleiben erhalten; ein Paketupdate ist dafür nicht erforderlich. <a href="/projects/grafik-visual-studio/interaktiv">Interaktiv-Neuerungen</a>.</p><p><strong>Paket 1.1.0 · Studio ab 0.1.292 · 49 Widgets · MIT.</strong> Eigenständige Renderer, angelehnt an <a href="https://github.com/typhosj/ioBroker.vis2-materialdesign" target="_blank" rel="noreferrer">ioBroker VIS2 Material Design von typhosj/Scrounger</a>. Die originalen MDI-Zuordnungen bleiben als lokale SVGs enthalten. Technische Paket-ID: <code>ugso.materialdesign</code>.</p><p><a href="/en/projects/grafik-visual-studio/materialdesign">English</a> · <a href="/fr/projects/grafik-visual-studio/materialdesign">Français</a> · <a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign" target="_blank" rel="noreferrer">Quellcode</a></p><h2 id="installation-und-erhaltene-einstellungen" tabindex="-1">Installation und erhaltene Einstellungen <a class="header-anchor" href="#installation-und-erhaltene-einstellungen" aria-label="Permalink to &quot;Installation und erhaltene Einstellungen&quot;">​</a></h2><ol><li>Das vorhandene Studio-Projekt als JSON sichern.</li><li>Studio auf <strong>0.1.292 oder neuer</strong> aktualisieren und neu starten.</li><li><a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign/blob/main/dist/ugso.materialdesign-1.1.0.wg" target="_blank" rel="noreferrer">Material Design 1.1.0 herunterladen</a>. Unter <strong>Einstellungen → Widget-Pakete → Lokal</strong> installieren oder den direkten GitHub-Dateilink verwenden.</li><li>Das Paket wird additiv aktualisiert. Danach die Seite neu laden und das bestehende Projekt prüfen.</li></ol><p>Die Installation schreibt <strong>keine Projektdatei um</strong>. Vorhandene Felder, Standardwerte, Reihenfolge und technische IDs bleiben geschützt. Neue Felder/Gruppen und Auswahlwerte werden ergänzt. Farben, Texte, Größen, Entitätszuordnungen und deaktivierte Gruppen bleiben gespeichert. Ältere veröffentlichte Paketdateien bleiben verfügbar.</p><p>Alte <strong>State-Multi</strong>-Widgets behalten den Wertezyklus. Mehrziel-Schreiben wird ausdrücklich als eigener Modus gewählt. Alte Advanced-Views behalten ihre Wertzuordnung; Seitenname/ID und numerischer Index sind zusätzliche Modi. Neue Widgets enthalten die entsprechenden Originalmodi. Ein Stilwechsel ändert keine Schreibziele.</p><h2 id="sprachen-und-gestaltung" tabindex="-1">Sprachen und Gestaltung <a class="header-anchor" href="#sprachen-und-gestaltung" aria-label="Permalink to &quot;Sprachen und Gestaltung&quot;">​</a></h2><p><strong>Material-Sprache</strong> folgt Studio oder wählt <strong>Deutsch, Englisch oder Französisch</strong> für Widget und Material-Eigenschaften. Benutzertexte sowie Seiten- und Entitäts-IDs werden nicht übersetzt. Die Studio-Gesamtoberfläche bleibt DE/EN; Französisch wird hier für Material angeboten.</p><p><strong>Klassisch</strong>, <strong>Material 3</strong> und <strong>Projektstandard</strong> bleiben wählbar. Das Farbschema folgt der Seite oder wird auf Hell/Dunkel festgelegt. Explizite Farben, Schriftgrößen und Abstände haben Vorrang. Die Vorschau enthält unverändert 26 Paletten; ihr klassischer weißer Hintergrund entspricht dem Original.</p><h2 id="widgets-und-originalfunktionen" tabindex="-1">Widgets und Originalfunktionen <a class="header-anchor" href="#widgets-und-originalfunktionen" aria-label="Permalink to &quot;Widgets und Originalfunktionen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Familie</th><th>Ergänzungen und Bedienung</th></tr></thead><tbody><tr><td>Buttons / Icon Buttons</td><td>Zustandstexte/-farben/-symbole, Druckfarbe, Taster, begrenzte Addition, neues Fenster, Navigation und zeitliche Entsperrung</td></tr><tr><td>State Multi</td><td>Bisheriger Zyklus oder mehrere Entitäten mit eigenem Wert und Verzögerung</td></tr><tr><td>Checkbox / Switch</td><td>Eigene Ein-/Aus-Werte oder boolescher Modus, Labelposition und echter Switch mit Spur/Griff</td></tr><tr><td>Input / Select / Autocomplete</td><td>Eingabeformen, Anhänge, Untertext/Zähler, Icons, Hover-/Auswahlfarben, Tastatur und Maske: # = Ziffer, A = Buchstabe, * = Buchstabe/Ziffer</td></tr><tr><td>Slider / Slider Round</td><td>Wirksame Griff-/Spurgröße, Grenzen/Schritt, Skala, Working-Entität, Schreiben während Bedienung oder beim Loslassen, Bogen/Startwinkel</td></tr><tr><td>Progress</td><td>Linear/rund, bestimmt/unbestimmt, Größe/Drehung, Schwellenfarben und Werttext</td></tr><tr><td>Value / Icon / Version</td><td>Zahl/Bool/Text/Datum/Dauer, Faktor/Offset, Bedingungen, Link und Änderungseffekt; statisches oder Zustandsicon; tatsächliche Paketversion</td></tr><tr><td>HTML Card</td><td>Titel/Untertitel, Bild, Kartenlayouts, Farben, Bildaktualisierung und isoliertes HTML</td></tr><tr><td>List / Icon List / Table / Alerts</td><td>Subtexte, Navigation/Links/Bedienung, JSON-Statusleisten, Bildspalten, Spaltenformatierung, feste Kopfzeile, Sortierung und Quittierung</td></tr><tr><td>Vier Diagramme</td><td>Balken, Pie/Donut, JSON und Recorder; bis zu vier Y-Achsen, Stacks, Füllung/Stufenlinien, Tooltips, Wertlabels, Paletten und Legendenposition</td></tr><tr><td>Calendar</td><td>Monat/Woche/Tag/Jahr/Liste, Kalenderwochen, Farben und Zeitraster in DE/EN/FR</td></tr><tr><td>Top App Bar</td><td>Modal/permanent/automatisch öffnender Drawer, Untereinträge und ausgewählter Index; bisherige Seitenlinks bleiben ein eigener Modus</td></tr><tr><td>Grid/Masonry / Advanced Views</td><td>Responsive Spalten, Sichtbarkeit je Ansicht, Wertzuordnung/Name/Index, boolesche Indizes 0/1, Vorladen und Erhalten geladener Ansichten</td></tr></tbody></table><p><strong>Erweiterte Optionen anzeigen</strong> blendet Details ein, ohne beim Ausblenden Werte zu löschen. Für Ziele, Ansichten, Datenreihen oder Menüpunkte die Anzahl setzen.</p><h2 id="home-assistant-und-daten" tabindex="-1">Home Assistant und Daten <a class="header-anchor" href="#home-assistant-und-daten" aria-label="Permalink to &quot;Home Assistant und Daten&quot;">​</a></h2><p>Geprüfte HA-Aktionen unterstützen <code>switch/input_boolean</code>, <code>number/input_number</code>, <code>text/input_text</code>, <code>select/input_select</code>, <code>button/input_button</code> mit <code>PRESS</code>, Leuchten-Helligkeit, Lüfter-Prozent und Cover-Position. Zustände, Auswahloptionen und Wertebereiche werden geprüft. Sensoren, Attribute und nicht verfügbare Entitäten bleiben Anzeigen.</p><p>Mehrziel-Aktionen laufen nacheinander und stoppen bei Fehler oder Seitenwechsel. Bereits ausgeführte Aktionen werden nicht zurückgerollt. Frei eingebbare HA-Dienste und ausführbare ioBroker-Bindings werden nicht übernommen.</p><p>Die Top App Bar im <strong>State-Modus</strong> schreibt den Index in ihre Entität. Eine <strong>Advanced View in Widget 8</strong> mit derselben Entität und <strong>Index-Modus</strong> zeigt die zugehörige lokale Studio-Seite. Ohne Entität kann der vorhandene Studio-Datenfluss verbunden werden; getrennte lokale Vorschauwerte werden nicht automatisch geteilt.</p><p>Listen lesen Editorzeilen oder JSON; Tabellen nutzen die konfigurierten Spaltenschlüssel. Optionales HTML in Listentexten wird bereinigt: keine Skripte, Event-Handler oder aktiven Einbettungen. HTML-Karten bleiben in einer Sandbox. Zielseiten können fremde iFrames blockieren.</p><p>Diagramme lesen <code>axisLabels/graphs</code>, <code>labels/datasets</code> oder Punktlisten. Recorder ist auf <strong>zehn Entitäten und 1–168 Stunden</strong> begrenzt. Die X-Achse berücksichtigt tatsächliche Zeitabstände. Aggregation: keine, Durchschnitt, Minimum, Maximum, Summe oder letzter Wert; Intervall in Minuten. Fehlende Zustände werden nicht erfunden.</p><p>Keine automatische ioBroker-Projektübernahme: HA-Entitäten, Recorder und Studio-Seiten ersetzen Objekt-IDs, History-Adapter und VIS-Views. SVG-Diagramme und Renderer sind eigene Umsetzungen; universelle Pixelgleichheit wird nicht zugesichert.</p><h2 id="prufung-und-veroffentlichung" tabindex="-1">Prüfung und Veröffentlichung <a class="header-anchor" href="#prufung-und-veroffentlichung" aria-label="Permalink to &quot;Prüfung und Veröffentlichung&quot;">​</a></h2><p>Browserprüfungen umfassen alle 49 Einträge in DE/EN/FR, Klassisch/Material 3 und Hell/Dunkel sowie Bedienabläufe. Ein Update mit echten Paketdateien erhält alte Projekte bytegenau. Tatsächliche HA-Gerätefunktionen zusätzlich in der eigenen Installation prüfen.</p><p><a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign/blob/main/comparison/materialdesign-widgetvergleich.json" target="_blank" rel="noreferrer">Vergleichsprojekt</a> · <a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign/blob/main/comparison/AUDIT-2026-10-12.md" target="_blank" rel="noreferrer">Ausgangsaudit</a></p><p>Im <a href="https://visualstudio.ugso-software.de/?lang=de" target="_blank" rel="noreferrer">Paketkatalog</a> <strong>1.1.0</strong>, Mindest-Studio <strong>0.1.292</strong>, ID <code>ugso.materialdesign</code> und MIT registrieren. GitHub-Veröffentlichung bedeutet keine automatische Katalogfreigabe. Prüfsumme: <code>dist/SHA256SUMS</code>.</p>',25)])])}const b=t(a,[["render",s]]);export{c as __pageData,b as default};
